/** @file joinpart.c @brief IRC JOIN/PART with channel access-policy enforcement. */
#include "commands.h"
#include "channel_policy.h"
#include "chanserv.h"
#include "config.h"
#include "modes.h"
#include "nospoof.h"
#include "numerics.h"
#include <stdio.h>
#include <string.h>
static int valid_channel_name(const char *name){return name!=NULL&&strchr(IRC_CHANNEL_PREFIXES,name[0])!=NULL&&strlen(name)<=IRC_CHANNEL_NAME_MAX&&strchr(name,' ')==NULL;}
static void join_one(Server *server,Client *client,const char *name,const char *key,unsigned int redirect_depth){Channel *channel;ChannelPrivilegeSet service_privileges;char message[IRCD_MESSAGE_BUFFER_SIZE];int first_member,explicitly_invited,protected_account,banned;if(!valid_channel_name(name)){client_sendf(client,ERR_NOSUCHCHANNEL,server->config.server_name,client->nick,name!=NULL?name:"*");return;}if(client->channel_count>=IRC_MAX_CHANNELS_PER_CLIENT){client_sendf(client,ERR_TOOMANYCHANNELS,server->config.server_name,client->nick,name);return;}channel=hash_get(&server->channels_by_name,name);if(channel==NULL)channel=server_get_or_create_channel(server,name);if(channel==NULL||channel_has_client(channel,client))return;chanserv_restore_channel(server,channel);service_privileges=chanserv_client_privileges(server,client,channel->name);protected_account=channel_privilege_has(service_privileges,CHANNEL_PRIV_OWNER|CHANNEL_PRIV_PROTECTED);explicitly_invited=channel_invite_has(channel,client->id);if(channel->key[0]!='\0'&&(key==NULL||strcmp(channel->key,key)!=0)){client_sendf(client,ERR_BADCHANNELKEY,server->config.server_name,client->nick,channel->name);return;}banned=protected_account?channel_client_is_banned_protected(channel,client):channel_client_is_banned(channel,client);if(banned){if(channel->ban_redirect[0]!='\0'&&redirect_depth<IRC_JOIN_REDIRECT_MAX&&valid_channel_name(channel->ban_redirect)){client_sendf(client,ERR_LINKCHANNEL,server->config.server_name,client->nick,channel->name,channel->ban_redirect);join_one(server,client,channel->ban_redirect,NULL,redirect_depth+1U);return;}client_sendf(client,ERR_BANNEDFROMCHAN,server->config.server_name,client->nick,channel->name);return;}if(channel->user_limit!=0U&&channel->member_count>=channel->user_limit){if(channel->limit_redirect[0]!='\0'&&redirect_depth<IRC_JOIN_REDIRECT_MAX&&valid_channel_name(channel->limit_redirect)){client_sendf(client,ERR_LINKCHANNEL,server->config.server_name,client->nick,channel->name,channel->limit_redirect);join_one(server,client,channel->limit_redirect,NULL,redirect_depth+1U);return;}client_sendf(client,ERR_CHANNELISFULL,server->config.server_name,client->nick,channel->name);return;}if(channel_mode_has(channel->modes,CHANNEL_MODE_REGONLY_JOIN)&&!client_mode_has(client->modes,CLIENT_MODE_REGISTERED)){client_sendf(client,ERR_NEEDREGGEDNICK,server->config.server_name,client->nick,channel->name);return;}if(channel_mode_has(channel->modes,CHANNEL_MODE_OPER_ONLY)&&!client_mode_has(client->modes,CLIENT_MODE_OPER|CLIENT_MODE_NETADMIN)){client_sendf(client,ERR_520,server->config.server_name,client->nick,channel->name);return;}if(channel_mode_has(channel->modes,CHANNEL_MODE_ADMIN_ONLY)&&!client_mode_has(client->modes,CLIENT_MODE_NETADMIN)){client_sendf(client,ERR_519,server->config.server_name,client->nick,channel->name);return;}if(channel_mode_has(channel->modes,CHANNEL_MODE_SECURE_ONLY)&&!client_mode_has(client->modes,CLIENT_MODE_SECURE)){client_sendf(client,ERR_SECUREONLYCHAN,server->config.server_name,client->nick,channel->name);return;}if(channel_mode_has(channel->modes,CHANNEL_MODE_INVITE_ONLY)&&!explicitly_invited&&!channel_client_is_invex(channel,client)){client_sendf(client,ERR_INVITEONLYCHAN,server->config.server_name,client->nick,channel->name);return;}if(!channel_join_throttle_allows(channel,client->id)){client_sendf(client,ERR_TOOMANYJOINS,server->config.server_name,client->nick,channel->name);return;}first_member=channel->member_count==0U;if(channel_add_client(channel,client)<0)return;channel_join_throttle_record(channel,client->id);if(explicitly_invited)(void)channel_invite_consume(channel,client->id);if(first_member&&!channel_mode_has(channel->modes,CHANNEL_MODE_REGISTERED))(void)channel_add_privileges(channel,client,CHANNEL_PRIV_OWNER|CHANNEL_PRIV_OPERATOR);if(channel_mode_has(channel->modes,CHANNEL_MODE_REGISTERED)&&service_privileges!=0U)(void)channel_add_privileges(channel,client,service_privileges);(void)snprintf(message,sizeof(message),":%s!%s@%s JOIN %s\r\n",client->nick,client->user,client->display_host,channel->name);channel_broadcast(channel,NULL,message);if(channel->topic[0]=='\0')client_sendf(client,RPL_NOTOPIC,server->config.server_name,client->nick,channel->name);else{client_sendf(client,RPL_TOPIC,server->config.server_name,client->nick,channel->name,channel->topic);client_sendf(client,RPL_TOPICWHOTIME,server->config.server_name,client->nick,channel->name,channel->topic_setter,(unsigned long)channel->topic_time);}command_send_names(channel,client);}
CommandResult command_join(Server *server,Client *client,char *params){char *name,*key;if(command_require_registered(client))return COMMAND_KEEP_CLIENT;if(params==NULL){client_sendf(client,ERR_NEEDMOREPARAMS,server->config.server_name,client->nick,"JOIN");return COMMAND_KEEP_CLIENT;}if(nospoof_version_restricted(server,client)){client_sendf(client,":%s NOTICE %s :You must respond to the CTCP VERSION request before joining channels.",server->config.server_name,client->nick);return COMMAND_KEEP_CLIENT;}name=strtok(params," ");key=strtok(NULL," ");join_one(server,client,name,key,0U);return COMMAND_KEEP_CLIENT;}
CommandResult command_part(Server *server,Client *client,char *params){char *name,*reason;Channel *channel;char message[IRCD_MESSAGE_BUFFER_SIZE];if(command_require_registered(client))return COMMAND_KEEP_CLIENT;if(params==NULL){client_sendf(client,ERR_NEEDMOREPARAMS,server->config.server_name,client->nick,"PART");return COMMAND_KEEP_CLIENT;}name=strtok(params," ");reason=strtok(NULL,"");if(reason!=NULL&&*reason==':')++reason;channel=hash_get(&server->channels_by_name,name);if(channel==NULL){client_sendf(client,ERR_NOSUCHCHANNEL,server->config.server_name,client->nick,name);return COMMAND_KEEP_CLIENT;}if(!channel_has_client(channel,client)){client_sendf(client,ERR_NOTONCHANNEL,server->config.server_name,client->nick,channel->name);return COMMAND_KEEP_CLIENT;}(void)snprintf(message,sizeof(message),":%s!%s@%s PART %s :%s\r\n",client->nick,client->user,client->display_host,channel->name,reason!=NULL?reason:IRC_DEFAULT_PART_REASON);channel_broadcast(channel,NULL,message);channel_remove_client(channel,client);server_remove_channel_if_empty(server,channel);return COMMAND_KEEP_CLIENT;}
